SET NOCOUNT ON;
DECLARE @Results TABLE(Test nvarchar(200));
INSERT CRM_Accounts(Name_AR,Owner_ID,Is_Active,Is_Deleted,AddedUser) VALUES(N'Self service customer',1,1,0,1);
DECLARE @Account int=CONVERT(int,SCOPE_IDENTITY());
INSERT CRM_Accounts(Name_AR,Owner_ID,Is_Active,Is_Deleted,AddedUser) VALUES(N'Other self service customer',1,1,0,1);
DECLARE @Other int=CONVERT(int,SCOPE_IDENTITY()),@Hash varbinary(32)=HASHBYTES('SHA2_256','test'),@Salt varbinary(32)=CRYPT_GEN_RANDOM(32);
EXEC Customer_SaveLogin @Actor=1,@AccountID=@Account,@Username=N'self-service-test',@Hash=@Hash,@Salt=@Salt;
DECLARE @Stamp uniqueidentifier=(SELECT SecurityStamp FROM Customer_Logins WHERE AccountID=@Account),@Version binary(8)=(SELECT Row_Version FROM CRM_Accounts WHERE ID=@Account);
DECLARE @Data xml=N'<row><Name_AR>Self service edited</Name_AR><Name_EN>Self Service</Name_EN><Email>self@example.invalid</Email><Website>https://example.invalid</Website></row>';
EXEC Customer_SaveProfile @Account,@Stamp,@Data,@Version,N'/FileManager/CustomerLogos/11111111111111111111111111111111.png';
IF NOT EXISTS(SELECT 1 FROM CRM_Accounts WHERE ID=@Account AND Name_AR=N'Self service edited' AND Logo_Url=N'/FileManager/CustomerLogos/11111111111111111111111111111111.png' AND Owner_ID=1 AND Is_Active=1 AND Modified_User IS NULL) THROW 51999,'Self profile/file logo URL failed',1;
IF NOT EXISTS(SELECT 1 FROM Customer_Portal_Activity WHERE AccountID=@Account AND Action='profile-update' AND ActorID IS NULL AND Before_Data IS NOT NULL AND After_Data IS NOT NULL) THROW 51999,'Profile audit missing',1;
IF EXISTS(SELECT 1 FROM Customer_Portal_Activity WHERE AccountID=@Account AND (CONVERT(nvarchar(max),After_Data) LIKE '%Logo_Data%' OR CONVERT(nvarchar(max),After_Data) LIKE '%89504E%')) THROW 51999,'Image bytes leaked into audit',1;
BEGIN TRY EXEC Customer_SaveProfile @Account,@Stamp,@Data,@Version;THROW 51999,'Stale profile saved',1;END TRY BEGIN CATCH IF ERROR_NUMBER()<>51910 THROW;END CATCH;
SELECT @Version=Row_Version FROM CRM_Accounts WHERE ID=@Account;
DECLARE @Attack xml=N'<row><Name_AR>Attempt</Name_AR><Owner_ID>2</Owner_ID><Is_Active>0</Is_Active></row>';
BEGIN TRY EXEC Customer_SaveProfile @Account,@Stamp,@Attack,@Version;THROW 51999,'Administrative fields accepted',1;END TRY BEGIN CATCH IF ERROR_NUMBER()<>51910 THROW;END CATCH;
INSERT @Results VALUES('Self profile/logo, metadata-only audit, optimistic concurrency and administrative-field denial');
DECLARE @ContactData xml=N'<row><Name_AR>جهة من البوابة</Name_AR><Name_EN>Portal Contact</Name_EN><Job_Title>مدير</Job_Title><Job_Title_EN>Manager</Job_Title_EN><Email>contact@example.invalid</Email><Is_Active>1</Is_Active></row>';
EXEC Customer_SaveContact @Account,@Stamp,0,@ContactData;
DECLARE @Contact int=(SELECT MAX(ID) FROM CRM_Contacts WHERE Account_ID=@Account);
SELECT @Version=Row_Version FROM CRM_Contacts WHERE ID=@Contact;
IF NOT EXISTS(SELECT 1 FROM CRM_Contacts WHERE ID=@Contact AND Name_EN=N'Portal Contact' AND Job_Title=N'مدير' AND Job_Title_EN=N'Manager' AND AddedUser IS NULL) THROW 51999,'Customer contact provenance/bilingual name failed',1;
DECLARE @AuditCount int=(SELECT COUNT(*) FROM Customer_Portal_Activity WHERE AccountID=@Account);
BEGIN TRY EXEC Customer_SaveContact @Account,@Stamp,0,N'<row><Name_AR>بدون إنجليزي</Name_AR><Is_Active>1</Is_Active></row>';THROW 51999,'Missing English name saved',1;END TRY BEGIN CATCH IF ERROR_NUMBER()<>51910 THROW;END CATCH;
BEGIN TRY EXEC CRM_Save_Contacts @Actor_ID=1,@Data=N'<row><Account_ID>1</Account_ID><Name_AR>بدون إنجليزي</Name_AR></row>';THROW 51999,'Admin missing English name saved',1;END TRY BEGIN CATCH IF ERROR_NUMBER()<>51201 THROW;END CATCH;
BEGIN TRY EXEC Customer_SaveContact @Account,@Stamp,0,N'<row><Name_AR>اختبار</Name_AR><Name_EN>Test</Name_EN><Job_Title_EN>Manager</Job_Title_EN><Is_Active>1</Is_Active></row>';THROW 51999,'Missing Arabic job title saved',1;END TRY BEGIN CATCH IF ERROR_NUMBER()<>51910 THROW;END CATCH;
BEGIN TRY EXEC Customer_SaveContact @Account,@Stamp,0,N'<row><Name_AR>اختبار</Name_AR><Name_EN>Test</Name_EN><Job_Title>مدير</Job_Title><Is_Active>1</Is_Active></row>';THROW 51999,'Missing English job title saved',1;END TRY BEGIN CATCH IF ERROR_NUMBER()<>51910 THROW;END CATCH;
BEGIN TRY EXEC CRM_Save_Contacts @Actor_ID=1,@Data=N'<row><Account_ID>1</Account_ID><Name_AR>اختبار</Name_AR><Name_EN>Test</Name_EN><Job_Title>مدير</Job_Title></row>';THROW 51999,'Admin missing English title saved',1;END TRY BEGIN CATCH IF ERROR_NUMBER()<>51201 THROW;END CATCH;
BEGIN TRY EXEC Customer_SaveProfile @Account,@Stamp,@Data,@Version,N'/FileManager/CustomerLogos/../../Web.config';THROW 51999,'Forged logo path accepted',1;END TRY BEGIN CATCH IF ERROR_NUMBER()<>51910 THROW;END CATCH;
IF (SELECT COUNT(*) FROM Customer_Portal_Activity WHERE AccountID=@Account)<>@AuditCount THROW 51999,'Failed mutation committed an audit success',1;
UPDATE CRM_Contacts SET Notes=N'Internal staff note' WHERE ID=@Contact;
SELECT @Version=Row_Version FROM CRM_Contacts WHERE ID=@Contact;
SET @ContactData=N'<row><Name_AR>جهة معدلة</Name_AR><Name_EN>Edited Portal Contact</Name_EN><Job_Title>محاسب</Job_Title><Job_Title_EN>Accountant</Job_Title_EN><Is_Active>0</Is_Active></row>';
EXEC Customer_SaveContact @Account,@Stamp,@Contact,@ContactData,@Version;
IF NOT EXISTS(SELECT 1 FROM CRM_Contacts WHERE ID=@Contact AND Is_Active=0 AND Job_Title_EN=N'Accountant' AND Notes=N'Internal staff note') THROW 51999,'Contact state/internal-note preservation failed',1;
BEGIN TRY EXEC Customer_SaveContact @Account,@Stamp,@Contact,@ContactData,@Version;THROW 51999,'Stale contact saved',1;END TRY BEGIN CATCH IF ERROR_NUMBER()<>51910 THROW;END CATCH;
INSERT CRM_Contacts(Account_ID,Name_AR,Name_EN,Is_Active,Is_Deleted,AddedUser) VALUES(@Other,N'جهة أخرى',N'Other Contact',1,0,1);
DECLARE @OtherContact int=CONVERT(int,SCOPE_IDENTITY());
SELECT @Version=Row_Version FROM CRM_Contacts WHERE ID=@OtherContact;
BEGIN TRY EXEC Customer_SaveContact @Account,@Stamp,@OtherContact,@ContactData,@Version;THROW 51999,'Other contact edited',1;END TRY BEGIN CATCH IF ERROR_NUMBER()<>51910 THROW;END CATCH;
BEGIN TRY EXEC Customer_DeleteContact @Account,@Stamp,@OtherContact,@Version;THROW 51999,'Other contact deleted',1;END TRY BEGIN CATCH IF ERROR_NUMBER()<>51910 THROW;END CATCH;
SELECT @Version=Row_Version FROM CRM_Contacts WHERE ID=@Contact;
EXEC Customer_DeleteContact @Account,@Stamp,@Contact,@Version;
IF NOT EXISTS(SELECT 1 FROM CRM_Contacts WHERE ID=@Contact AND Is_Deleted=1) THROW 51999,'Soft delete failed',1;
BEGIN TRY EXEC Customer_DeleteContact @Account,@Stamp,@Contact,@Version;THROW 51999,'Delete replay accepted',1;END TRY BEGIN CATCH IF ERROR_NUMBER()<>51910 THROW;END CATCH;
IF (SELECT COUNT(*) FROM Customer_Portal_Activity WHERE AccountID=@Account AND Action IN('contact-create','contact-update','contact-delete'))<>3 THROW 51999,'Contact audit lifecycle incomplete',1;
INSERT @Results VALUES('Contact add/edit/state/soft delete, bilingual validation, stale/replay denial and account isolation');
UPDATE Customer_Logins SET IsActive=0 WHERE AccountID=@Account;
SELECT @Version=Row_Version FROM CRM_Accounts WHERE ID=@Account;
BEGIN TRY EXEC Customer_SaveProfile @Account,@Stamp,@Data,@Version;THROW 51999,'Disabled customer saved profile',1;END TRY BEGIN CATCH IF ERROR_NUMBER()<>51911 THROW;END CATCH;
BEGIN TRY EXEC Customer_SaveContact @Account,@Stamp,0,@ContactData;THROW 51999,'Disabled customer saved contact',1;END TRY BEGIN CATCH IF ERROR_NUMBER()<>51911 THROW;END CATCH;
UPDATE Customer_Logins SET IsActive=1 WHERE AccountID=@Account;
EXEC Customer_LogLoginFailure N'self-service-test';EXEC Customer_LogLoginFailure N'unknown-test-identity';
EXEC Customer_LogActivity @Account,@Stamp,'logout';
IF NOT EXISTS(SELECT 1 FROM Customer_Portal_Activity WHERE AccountID=@Account AND Action='login-failed') OR NOT EXISTS(SELECT 1 FROM Customer_Portal_Activity WHERE AccountID IS NULL AND Action='login-failed') THROW 51999,'Failed login audit missing',1;
IF NOT EXISTS(SELECT 1 FROM CRM_v_Activity WHERE Account_ID=@Account AND Source_Name=N'بوابة العميل' AND Entity=N'Contacts') THROW 51999,'Unified customer activity missing',1;
DECLARE @AdminContact xml=CONVERT(xml,CONCAT(N'<row><Account_ID>',@Account,N'</Account_ID><Name_AR>جهة الإدارة</Name_AR><Name_EN>Admin Contact</Name_EN><Job_Title>مدير</Job_Title><Job_Title_EN>Manager</Job_Title_EN></row>'));
DECLARE @Saved TABLE(ID int,Row_Version binary(8));
INSERT @Saved EXEC CRM_Save_Contacts @Actor_ID=1,@Data=@AdminContact;
IF NOT EXISTS(SELECT 1 FROM CRM_v_Activity WHERE Account_ID=@Account AND Source_Name=N'إدارة النظام' AND Entity=N'Contacts') THROW 51999,'Unified admin activity missing',1;
INSERT @Results VALUES('Disabled-session write denial, failed/successful auth audit, unified administrator/customer sources');
IF NOT EXISTS(SELECT 1 FROM Customer_Portal_Activity WHERE Action='credentials' AND After_Data.exist('/login/PasswordChanged')=1) THROW 51999,'Safe credential change snapshot missing',1;
IF EXISTS(SELECT 1 FROM Customer_Portal_Activity WHERE Before_Data.exist('//*[local-name()=("PasswordHash","Salt","SecurityStamp","Image_Data","Logo_Data")]')=1 OR After_Data.exist('//*[local-name()=("PasswordHash","Salt","SecurityStamp","Image_Data","Logo_Data")]')=1) THROW 51999,'Sensitive bytes leaked into customer audit',1;
INSERT @Results VALUES('Credential audit stores safe state/change flag only; hashes, stamps and image data are absent');
SELECT * FROM @Results;
